import React, { Component } from 'react'
import { connect } from 'react-redux'
import _ from 'lodash'
import {
  Row,
  Col,
  Form,
  Select,
  Divider,
  Input,
  Button,
  Icon,
  notification,
  Spin
} from 'antd'
import { CreateTemplateWrapper } from './component.style'
import ColumnFields from './columnFields'
import ReconForm from './reconForm'
import PackageDistribution from './packageDistribution'
import PolicyActions from '../../../../redux/policy/actions'
import PartnerFileTemplateActions from '../../../redux/partnerFileTemplate/actions'
import loadingAction from '../../../../redux/loading/actions'
import ErrorAction from '../../../../redux/error/actions'
import PromoActions from '../../../redux/promo/actions'

const FormItem = Form.Item
const { Option } = Select

const { getPackageList } = PromoActions
const { getProducts } = PolicyActions
const {
  listTimezone,
  createFileTemplate,
  getColumnTypes,
  getFileTemplateStaticData,
  getDefaultReconConfig
} = PartnerFileTemplateActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction

const packageCodeMandatoryOperations = ['RECON', 'CLAIM']

class CreateTemplate extends Component {
  constructor (props) {
    super(props)
    this.state = {
      columnCount: (props.template && props.template.columns.length) || 1,
      columnsData: props.template && props.template.columns,
      editing: props.template,
      operationType: undefined,
      reconData: (props.template && props.template.recon_data) || [],
      selectedPackageCodes:
        (props.templateData && props.templateData.package_code.split(',')) ||
        []
    }
  }

  componentDidMount () {
    this.props.listTimezone()
    this.props.resetLoadingRedux([
      'CREATE_FILE_TEMPLATE',
      'GET_DEFAULT_RECON_CONFIG'
    ])
    this.props.resetErrorRedux([
      'CREATE_FILE_TEMPLATE',
      'GET_DEFAULT_RECON_CONFIG'
    ])
    this.props.getFileTemplateStaticData()
    if (this.state.editing) {
      const productCode = this.props.template.product_code
      this.props.getPackageList(productCode)
    }
    const formValues = this.props.form.getFieldsValue()
    const productCode = formValues.product_code
    const packageCode = formValues.package_code
    if (productCode) {
      this.handleProductChange(productCode)
    }
    if (packageCode) {
      this.setState({ selectedPackageCodes: packageCode })
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { editing, reconData } = this.state
    if (nextProps.createTemplateLoading === false) {
      notification[nextProps.createTemplateError ? 'error' : 'success']({
        message: nextProps.createTemplateStatus
      })
      if (nextProps.createTemplateError === false) {
        this.props.nextStep()
      } else {
        this.props.stepStateChange('error')
      }
      this.props.resetLoadingRedux(['CREATE_FILE_TEMPLATE'])
      this.props.resetErrorRedux(['CREATE_FILE_TEMPLATE'])
    }
    if (
      this.props.form.getFieldValue('operation_type') &&
      this.props.form.getFieldValue('operation_type') !==
        this.state.operationType
    ) {
      this.setState({
        operationType: this.props.form.getFieldValue('operation_type')
      })
    }
    const formValues = nextProps.form.getFieldsValue()
    const productCode = formValues.product_code
    const partnerCode = formValues.partner_code
    const operationType = formValues.operation_type
    if (
      !editing &&
      operationType === 'RECON' &&
      partnerCode &&
      productCode &&
      (partnerCode !== this.state.partnerCode ||
        productCode !== this.state.productCode ||
        operationType !== this.state.operationType)
    ) {
      this.setState({ partnerCode, productCode, operationType })
      this.props.getDefaultReconConfig({
        query: {
          partner_code: partnerCode,
          product_code: productCode
        }
      })
    }
    if (
      nextProps.defaultConfigLoading === false &&
      nextProps.defaultConfigError === false
    ) {
      if (nextProps.defaultConfig.data) {
        if (reconData.length === 0) {
          reconData.push(nextProps.defaultConfig.data)
          this.setState({ reconData })
        }
        notification.info({
          message: `Default config exists for ${productCode}`
        })
      } else {
        this.setState({ reconData: [] })
      }
      this.props.resetLoadingRedux(['GET_DEFAULT_RECON_CONFIG'])
      this.props.resetErrorRedux(['GET_DEFAULT_RECON_CONFIG'])
    }
    if (
      nextProps.defaultConfigLoading === false &&
      nextProps.defaultConfigError
    ) {
      this.setState({ reconData: [] })
      this.props.resetLoadingRedux(['GET_DEFAULT_RECON_CONFIG'])
      this.props.resetErrorRedux(['GET_DEFAULT_RECON_CONFIG'])
    }
  }

  handleSubmit = (e) => {
    const { selectedPackageCodes } = this.state
    const { operationType } = this.state

    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { reconData, editing } = this.state
        const finalValues = {}
        const columns = []
        const packageDistribution = {}

        Object.keys(values).map((key) => {
          if (key.includes('-')) {
            const [fieldKey, index] = key.split('-')
            const intIndex = parseInt(index)
            if (!columns[intIndex]) {
              columns[intIndex] = {}
            }
            if (fieldKey === 'required') {
              if (values[key]) {
                columns[intIndex][fieldKey] = 'True'
              } else {
                columns[intIndex][fieldKey] = 'False'
              }
            } else {
              columns[intIndex][fieldKey] = values[key]
            }
          } else {
            finalValues[key] = values[key]
          }
          return key
        })
        if (values.operation_type === 'RECON') {
          const defaultConfigExists = _.filter(reconData, [
            'package_code',
            null
          ])
          const addedExtraValue = _.map(reconData, function (element) {
            return _.extend({}, element, {
              raw_sql_query_check: _.get(element, 'raw_sql_query_check', true)
            })
          })
          if (defaultConfigExists.length > 0) {
            Object.assign(finalValues, {
              recon_data: addedExtraValue
            })
          } else {
            notification.error({ message: 'Please add default config' })
            return
          }
          const reconCsvConversionMapping = {}
          reconCsvConversionMapping.unique_key = values.unique_key
          reconCsvConversionMapping.premium = values.premium
          delete values.unique_key
          delete values.premium
          Object.assign(finalValues, {
            recon_csv_conversion_mapping: reconCsvConversionMapping
          })
        }
        Object.assign(finalValues, {
          package_code:
            values.package_code && values.package_code.length
              ? values.package_code.join(',')
              : null
        })
        if (editing) {
          Object.assign(finalValues, {
            operation: editing.operation,
            edit_flag: true
          })
        } else {
          Object.assign(finalValues, {
            edit_flag: false
          })
        }
        finalValues.columns = columns

        selectedPackageCodes.forEach((packageCode) => {
          packageDistribution[packageCode] = {
            distribution: values[`${packageCode}-percentage`],
            sort: values[`${packageCode}-priority`]
          }
        })

        finalValues.custom_config = { ...packageDistribution }

        if (selectedPackageCodes.length > 0 && operationType) {
          if (this.handlPackageDistribution()) {
            this.props.createFileTemplate({
              body: finalValues
            })
          }
        } else {
          this.props.createFileTemplate({
            body: finalValues
          })
        }
      }
    })
  };

  getColumnsData = () => {
    const formValues = this.props.form.getFieldsValue()
    const finalValues = {}
    const columns = []

    Object.keys(formValues).forEach((key) => {
      if (key.includes('-')) {
        const [fieldKey, index] = key.split('-')
        const intIndex = parseInt(index)
        if (!columns[intIndex]) {
          columns[intIndex] = {}
        }
        if (fieldKey === 'required') {
          if (formValues[key]) {
            columns[intIndex][fieldKey] = 'True'
          } else {
            columns[intIndex][fieldKey] = 'False'
          }
        } else {
          columns[intIndex][fieldKey] = formValues[key]
        }
      } else {
        finalValues[key] = formValues[key]
      }
    })
    return columns
  };

  handleProductChange = (product) => {
    this.setState({ productCode: product })
    this.props.getPackageList(product)
  };

  handlePartnerChange = (value) => {
    this.props.form.resetFields(['product_code', 'package_code'])
    this.props.getProducts({ query: { partner_code: value } })
    this.setState({
      partnerCode: value
    })
  };

  handleRemoveColumn = (index) => {
    const { columnCount, columnsData } = this.state
    columnsData && columnsData.splice(index, 1)
    this.setState({
      columnCount: columnCount - 1,
      columnsData: columnsData || []
    })
  };

  handleAddColumn = (index) => {
    const { columnCount } = this.state
    this.setState({ columnCount: columnCount + 1 })
  };

  saveReconData = (reconData) => {
    this.setState({ reconData })
  };

  handlePackageCodeChange = (value) => {
    this.setState({ selectedPackageCodes: value })
  };

  handlPackageDistribution = () => {
    const formValues = this.props.form.getFieldsValue()
    const { selectedPackageCodes } = this.state
    const priority = selectedPackageCodes.map(
      (packageCode) => formValues[`${packageCode}-priority`]
    )
    const priorityFilter = priority.filter(
      (item, index) => priority.indexOf(item) !== index && item !== undefined
    )

    if (priorityFilter.length > 0) {
      notification.error({
        message: 'Some packages have same priority'
      })
      return false
    }
    const percentage = selectedPackageCodes.map(
      (packageCode) => formValues[`${packageCode}-percentage`]
    )
    const sumPercentage = percentage.reduce(
      (acc, value) => Number(acc) + Number(value),
      0
    )
    if (sumPercentage !== 100 && sumPercentage) {
      notification.error({
        message: 'sum of package distribution should be equal to 100 '
      })
      return false
    }

    return true
  };

  packageDistributionData = () => {
    const formValues = this.props.form.getFieldsValue()
    const { selectedPackageCodes } = this.state
    const customPackage = selectedPackageCodes.map((packageCode) => {
      return {
        [packageCode]: {
          distribute: formValues[`${packageCode}-percentage`],
          sort: formValues[`${packageCode}-priority`]
        }
      }
    })
    return Object.assign({}, customPackage)
  };

  render () {
    const {
      form,
      partners = [],
      partnersLoading,
      products = [],
      productsLoading,
      timezones,
      template = {},
      createTemplateLoading,
      formValues,
      fileTemplateStaticData = {},
      packageListLoading,
      packageList = []
    } = this.props
    const { getFieldDecorator } = form
    const {
      partner_code: partnerCode,
      product_code: productCode,
      package_id: packageId,
      package_code: packageCode,
      name,
      custom_config: customConfig,
      operation_type: operationtype,
      recon_csv_conversion_mapping: reconCsvConversionMapping,
      benefit_slug: benefitSlug
    } = template

    const {
      columnCount,
      editing,
      columnsData = [],
      operationType,
      selectedPackageCodes,
      reconData
    } = this.state
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 6 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 12 }
      }
    }
    const columnsValues = this.getColumnsData()

    return (
      <CreateTemplateWrapper>
        <Spin spinning={!!createTemplateLoading}>
          <Form {...formItemLayout} onSubmit={this.handleSubmit}>
          <div className="email-wrapper">
              <span className="bold">Email:</span>{" "}
              {template?.file_template_email_id}
            </div>
            <Row type='flex' justify='space-around'>
              <FormItem label='Partner'>
                {getFieldDecorator('partner_code', {
                  initialValue: partnerCode || formValues.partner_code
                })(
                  <Select
                    placeholder='Select Partner'
                    className='select'
                    dropdownMatchSelectWidth={false}
                    showSearch
                    filterOption={(input, option) =>
                      option.props.children
                        .join('')
                        .toLowerCase()
                        .includes(input.toLowerCase())}
                    onChange={this.handlePartnerChange}
                    loading={!editing && !!partnersLoading}
                    disabled={
                      !!partnersLoading || editing || formValues.partner_code
                    }
                  >
                    {partners.map(({ name, code }) => (
                      <Option value={code} key={code}>
                        {name} - {code}
                      </Option>
                    ))}
                  </Select>
                )}
              </FormItem>
              <FormItem label='Product'>
                {getFieldDecorator('product_code', {
                  rules: [
                    { required: true, message: 'Please choose product!' }
                  ],
                  initialValue: productCode || formValues.product_code
                })(
                  <Select
                    placeholder='Select Product'
                    className='select'
                    showSearch
                    dropdownMatchSelectWidth={false}
                    onChange={this.handleProductChange}
                    filterOption={(input, option) =>
                      option.props.value
                        .toLowerCase()
                        .includes(input.toLowerCase())}
                    loading={!editing && !!productsLoading}
                    disabled={
                      !!productsLoading || editing || formValues.product_code
                    }
                  >
                    {products.map(({ name }) => (
                      <Option value={name} key={name}>
                        {name}
                      </Option>
                    ))}
                  </Select>
                )}
              </FormItem>
              <FormItem label='Type'>
                {getFieldDecorator('operation_type', {
                  rules: [
                    {
                      required: true,
                      message: 'Please choose Operation type!'
                    }
                  ],
                  initialValue: operationtype || formValues.operation_type
                })(
                  <Select
                    placeholder='Select Operation Type'
                    className='select'
                    onChange={(operationType) =>
                      this.setState({ operationType })}
                    showSearch
                    disabled={editing || formValues.operation_type}
                    filterOption={(input, option) =>
                      option.props.children
                        .join('')
                        .toLowerCase()
                        .includes(input.toLowerCase())}
                  >
                    {Object.keys(fileTemplateStaticData).length > 0 &&
                      fileTemplateStaticData['operation-type-data'].map(
                        ({ display_name: displayName, value }) => (
                          <Option value={value} key={value}>
                            {displayName}
                          </Option>
                        )
                      )}
                  </Select>
                )}
              </FormItem>
            </Row>
            <Divider />
            <FormItem label='Template Name'>
              {getFieldDecorator('template_name', {
                rules: [
                  { required: true, message: 'Please add template name!' }
                ],
                initialValue: name
              })(<Input disabled={editing} />)}
            </FormItem>
            <FormItem label='Package Code'>
              {getFieldDecorator('package_code', {
                rules: [
                  {
                    required: packageCodeMandatoryOperations.includes(
                      form.getFieldValue('operation_type')
                    ),
                    message: 'Please choose Package Code!'
                  }
                ],
                initialValue:
                  packageCode && packageCode.length
                    ? packageCode.split(',')
                    : undefined
              })(
                <Select
                  placeholder='Select package code'
                  className='package-select'
                  optionFilterProp='children'
                  mode='multiple'
                  onChange={this.handlePackageCodeChange}
                  dropdownMatchSelectWidth={false}
                  loading={!!packageListLoading}
                  showSearch
                  filterOption={(input, option) =>
                    option.props.children
                      .toLowerCase()
                      .includes(input.toLowerCase())}
                >
                  {packageList.map(
                    ({
                      package_code: packageCode,
                      package_code_slug: packageCodeSlug
                    }) => (
                      <Option
                        value={
                          form.getFieldValue('operation_type') === 'CLAIM'
                            ? packageCodeSlug
                            : packageCode
                        }
                        key={packageCode}
                      >
                        {form.getFieldValue('operation_type') === 'CLAIM'
                          ? packageCodeSlug
                          : packageCode}
                      </Option>
                    )
                  )}
                </Select>
              )}
            </FormItem>

            <FormItem label='Package ID'>
              {getFieldDecorator('package_id', {
                initialValue: packageId
              })(<Input />)}
            </FormItem>
            {operationType === 'CLAIM' && (
              <FormItem label='Benefit Slug'>
                {getFieldDecorator('benefit_slug', {
                  rules: [
                    { required: true, message: 'Please add Benefit Slug!' }
                  ],
                  initialValue: benefitSlug
                })(<Input />)}
              </FormItem>
            )}
            <Row align='middle'>
              <Col span={6} className='column-label'>
                Columns:
              </Col>
              <Col span={16}>
                {[...Array(columnCount)].map((i, index) => (
                  <Row key={index} type='flex'>
                    <ColumnFields
                      form={form}
                      key={index}
                      index={index}
                      columnTypes={fileTemplateStaticData['column-type-data']}
                      columnsData={columnsData[index]}
                      dateTimeFormat={
                        fileTemplateStaticData['datetime-format-data']
                      }
                      dateFormat={fileTemplateStaticData['date-format-data']}
                    />
                    {columnCount === 1
                      ? (
                        <Icon
                          type='plus-circle'
                          className='add-icon'
                          onClick={() =>
                            this.setState({ columnCount: columnCount + 1 })}
                        />
                        )
                      : index === columnCount - 1
                        ? (
                          <div>
                            <Icon
                              type='minus-circle'
                              className='minus-icon'
                              onClick={() => this.handleRemoveColumn(index)}
                            />
                            <Icon
                              type='plus-circle'
                              className='add-icon'
                              onClick={() =>
                                this.handleAddColumn()}
                            />
                          </div>
                          )
                        : (
                          <Icon
                            type='minus-circle'
                            className='minus-icon'
                            onClick={() => this.handleRemoveColumn(index)}
                          />
                          )}
                  </Row>
                ))}
              </Col>
            </Row>
            {(operationType === 'POLICY_DISTRIBUTION' || operationType === 'POLICY_BY_UI_CONFIG_DISTRIBUTION') && selectedPackageCodes.length > 0 && (
              <Row align='middle'>
                <Col span={6} className='column-label'>
                  Packages:
                </Col>
                <Col span={16}>
                  <PackageDistribution
                    form={form}
                    packages={selectedPackageCodes}
                    customConfig={customConfig}
                  />
                </Col>
              </Row>
            )}
            {operationType === 'RECON' && (
              <ReconForm
                form={form}
                timezones={timezones}
                templateData={template}
                reconCsvConversionMapping={reconCsvConversionMapping}
                saveReconData={this.saveReconData}
                selectedPackageCodes={selectedPackageCodes}
                reconData={reconData}
                columnsValues={columnsValues}
                operationType={form.getFieldValue('operation_type')}
              />
            )}
            <Button htmlType='submit' type='primary'>
              Submit Config
            </Button>
          </Form>
        </Spin>
      </CreateTemplateWrapper>
    )
  }
}

const WrappedCreateTemplate = Form.create()(CreateTemplate)

export default connect(
  (state) => ({
    partners: state.Policy.partners,
    partnersLoading: state.Loading.GET_PARTNERS,
    partnersError: state.Error.GET_PARTNERS,

    products: state.Policy.products,
    productsLoading: state.Loading.GET_PRODUCTS,
    productsError: state.Error.GET_PRODUCTS,

    fileTemplateTypes: state.PartnerFileTemplate.fileTemplatesType,
    timezones: state.PartnerFileTemplate.timezones,
    columnTypes: state.PartnerFileTemplate.columnTypes,

    createTemplateLoading: state.Loading.CREATE_FILE_TEMPLATE,
    createTemplateError: state.Error.CREATE_FILE_TEMPLATE,
    createTemplateStatus: state.PartnerFileTemplate.createTemplateStatus,

    packageList: state.PromoDetails.packageLists,
    packageListLoading: state.Loading.GET_COUPON_PACKAGE_LIST,

    fileTemplateStaticData: state.PartnerFileTemplate.fileTemplateStaticData,

    defaultConfig: state.PartnerFileTemplate.defaultConfig,
    defaultConfigLoading: state.Loading.GET_DEFAULT_RECON_CONFIG,
    defaultConfigError: state.Error.GET_DEFAULT_RECON_CONFIG
  }),
  {
    getProducts,
    listTimezone,
    createFileTemplate,
    getColumnTypes,
    resetLoadingRedux,
    resetErrorRedux,
    getPackageList,
    getFileTemplateStaticData,
    getDefaultReconConfig
  }
)(WrappedCreateTemplate)
