import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Card, Steps, Icon, Button, Upload, Row, notification } from 'antd'
import { PartnerFileTemplateStyleWrapper } from './index.style'
import BasicForm from './components/basicForm'
import ListTemplates from './components/listTemplate'
import CreateTemplate from './components/createTemplate'
import DonePage from './components/done'
import PartnerFileTemplateActions from '../../redux/partnerFileTemplate/actions'
import loadingAction from '../../../redux/loading/actions'
import ErrorAction from '../../../redux/error/actions'
import PolicyActions from '../../../redux/policy/actions'

const { getFileTemplatesTypes, importTemplate, getFileTemplateStaticData } = PartnerFileTemplateActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction
const { getProducts, getPartners } = PolicyActions

const { Step } = Steps

const initialState = {
  stepsConfig: [
    { title: 'Basic Form', status: 'process', icon: 'form' },
    { title: 'Choose Template', status: 'wait', icon: 'container' },
    { title: 'Fill Details', status: 'wait', icon: 'snippets' },
    { title: 'Done', status: 'wait', icon: 'smile-o' }
  ],
  current: 0,
  template: undefined,
  formValues: {}
}

class PartnerFileTemplate extends Component {
  constructor (props) {
    super(props)
    this.state = initialState
  }

  componentDidMount () {
    const { partners } = this.props
    if (partners.length < 1) {
      this.props.getPartners()
    }
    this.props.getFileTemplateStaticData()
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.importTemplateLoading === false) {
      notification[nextProps.importTemplateError ? 'error' : 'success']({ message: nextProps.importTemplateStatus })
      this.props.resetLoadingRedux(['GET_FILE_TEMPLATES', 'IMPORT_TEMPLATE'])
      this.props.resetErrorRedux(['GET_FILE_TEMPLATES', 'IMPORT_TEMPLATE'])
    }
  }

  nextStep = (template) => {
    const { current, stepsConfig } = this.state
    let tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'finish'
    tempStepsConfig[current + 1].status = 'process'
    this.setState({ stepsConfig: tempStepsConfig, current: current + 1 })
    if (template) {
      this.setState({ template })
    }
  }

  handlePrevious = () => {
    const { current, stepsConfig } = this.state
    let tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'wait'
    tempStepsConfig[current - 1].status = 'process'
    this.setState({ stepsConfig: tempStepsConfig, current: current - 1, template: undefined })
  }

  stepStateChange = (state) => {
    const { current, stepsConfig } = this.state
    let tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = state
    this.setState({ stepsConfig: tempStepsConfig })
  }

  handleUpload = file => {
    const reader = new FileReader()

    reader.onload = e => {
      const result = JSON.parse(e.target.result)
      this.props.importTemplate({
        body: {
          ...result
        }
      })
    }
    reader.readAsText(file)

    return false
  }

  saveValues = (formValues) => {
    this.setState({ formValues })
  }

  resetData = () => {
    this.setState(initialState)
  }

  render () {
    const { importTemplateLoading } = this.props
    const { stepsConfig = [], current, template, formValues } = this.state

    return (
      <PartnerFileTemplateStyleWrapper>
        <Card>
          <Row type='flex' justify='space-between'>
            <div className='heading'>Create File Template</div>
            {
              current === 0 &&
              <Upload
                accept='.json'
                showUploadList={false}
                beforeUpload={this.handleUpload}
              >
                <Button
                  type='default'
                  className='import'
                  loading={importTemplateLoading}
                >
                  Import File Template
                </Button>
              </Upload>
            }
          </Row>
          <Steps current={current}>
            {
              stepsConfig.map(({ title, status, icon }) => <Step status={status} title={title} icon={<Icon type={icon} />} />)
            }
          </Steps>
          {
            current === 0 &&
            <Card>
              <BasicForm
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
                saveValues={this.saveValues}
              />
            </Card>
          }
          {
            current === 1 &&
            <Card>
              <ListTemplates
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
                formValues={formValues}
              />
            </Card>
          }
          {
            current === 2 &&
            <Card>
              <CreateTemplate
                template={template}
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
                formValues={formValues}
              />
            </Card>
          }
          {
            current === 3 &&
            <Card>
              <DonePage
                nextStep={this.nextStep}
                stepStateChange={this.stepStateChange}
                resetData={this.resetData}
              />
            </Card>
          }
          {
            current !== 0 && current !== 3 &&
            <Button onClick={this.handlePrevious} className='back-button'>
              Back
            </Button>
          }
        </Card>
      </PartnerFileTemplateStyleWrapper>
    )
  }
}

export default connect(
  state => ({
    partners: state.Policy.partners,
    products: state.Policy.products,
    internalUsers: state.User.internalUsers,

    partnersLoading: state.Loading.GET_PARTNERS,
    partnersError: state.Error.GET_PARTNERS,

    productsLoading: state.Loading.GET_PRODUCTS,
    productsError: state.Error.GET_PRODUCTS,

    packageList: state.PromoDetails.packageLists,
    packageListLoading: state.Loading.GET_COUPON_PACKAGE_LIST,
    packageListError: state.Error.GET_COUPON_PACKAGE_LIST,

    importTemplateLoading: state.Loading.IMPORT_TEMPLATE,
    importTemplateError: state.Error.IMPORT_TEMPLATE,
    importTemplateStatus: state.PartnerFileTemplate.importTemplateStatus
  }),
  {
    getPartners,
    getProducts,
    resetLoadingRedux,
    resetErrorRedux,
    getFileTemplatesTypes,
    importTemplate,
    getFileTemplateStaticData
  }
)(PartnerFileTemplate)
