import React, { Component } from 'react'
import { connect } from 'react-redux'
import { FileTemplateWrapper } from './component.style'
import { Row, Button, notification, Checkbox, Result, Switch, Spin } from 'antd'
import PartnerFileTemplateActions from '../../../redux/partnerFileTemplate/actions'
import loadingAction from '../../../../redux/loading/actions'
import ErrorAction from '../../../../redux/error/actions'

const { exportTemplate, changeTemplateStatus, listFileTemplate } = PartnerFileTemplateActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction

class ListTemplate extends Component {
  state = {
    checkedTemplate: []
  }

  componentDidMount () {
    this.props.resetErrorRedux(['EXPORT_TEMPLATE', 'TEMPLATE_CHANGE_STATUS'])
    this.props.resetLoadingRedux(['EXPORT_TEMPLATE', 'TEMPLATE_CHANGE_STATUS'])
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.exportTemplateLoading === false) {
      if (nextProps.exportTemplateError === false) {
        notification['success']({ message: 'File Template Exported Successfully!' })
      } else {
        notification['error']({ message: 'File Template Export Failed' })
      }
      this.props.resetErrorRedux(['EXPORT_TEMPLATE'])
      this.props.resetLoadingRedux(['EXPORT_TEMPLATE'])
    }
    if (nextProps.changeTemplateStatusLoading === false) {
      if (nextProps.changeTemplateStatusError === false) {
        notification['success']({ message: 'Status changed successfully!' })
        this.props.listFileTemplate({
          query: {
            ...this.props.formValues
          }
        })
      } else {
        notification['error']({ message: 'Something went wrong. Please try again.' })
      }
      this.props.resetErrorRedux(['TEMPLATE_CHANGE_STATUS'])
      this.props.resetLoadingRedux(['TEMPLATE_CHANGE_STATUS'])
    }
  }

  handleNext = () => {
    this.props.nextStep()
  }

  handleEdit = (template) => {
    this.props.nextStep(template)
  }

  handleExport = () => {
    const { checkedTemplate } = this.state
    if (checkedTemplate.length > 0) {
      this.props.exportTemplate({
        body: {
          'file_template_ids': checkedTemplate
        }
      })
    } else {
      notification['error']({ message: 'Please select template to export' })
    }
  }

  handleTemplateStatusChange = (checked, id) => {
    this.props.changeTemplateStatus({
      body: {
        'template_id': id,
        'is_active': checked
      }
    })
  }

  render () {
    const { fileTemplates = [], exportTemplateLoading, listTemplateLoading, changeTemplateStatusLoading } = this.props

    return (
      <FileTemplateWrapper>
        <Spin spinning={!!listTemplateLoading || !!changeTemplateStatusLoading}>
          {
            fileTemplates.length > 0 &&
            <Row type='flex' justify='end'>
              <Button onClick={this.handleExport} loading={!!exportTemplateLoading} className='export-button'>
                Export
              </Button>
            </Row>
          }
          {
            fileTemplates.length > 0
              ? <Checkbox.Group onChange={(checkedTemplate) => this.setState({ checkedTemplate })}>
                {fileTemplates.map(template =>
                  <Row type='flex' align='middle'>
                    <Checkbox value={template.id} />
                    <div className='template-container'>
                      <Row type='flex' justify='space-between' align='bottom'>
                        <div className='template-header'>{template.name.toUpperCase()}</div>
                        <Button onClick={() => this.handleEdit(template)} className='edit-button'>
                          Edit
                        </Button>
                      </Row>
                      <div className='template-content'><span className='head'>Partner -</span> {template.partner_code}</div>
                      <div className='template-content'><span className='head'>Product -</span> {template.product_code}</div>
                      <div className='template-content'><span className='head'>Template Type -</span> {template.operation_type}</div>
                      <div className='template-content'><span className='head'>Active -</span>
                        <Switch
                          className='switch'
                          defaultChecked={template['is_active']}
                          onChange={(e) => this.handleTemplateStatusChange(e, template.id)}
                        />
                      </div>
                      <div className='template-content'><span className='head'>Email -</span> {template?.file_template_email_id}</div>
                    </div>
                  </Row>
                )}
              </Checkbox.Group>
              : <Row type='flex' justify='center'>
                <Result
                  status='404'
                  title='Not Found'
                  subTitle='Sorry, no template found'
                />
              </Row>
          }
          <Row type='flex' justify='end'>
            <Button
              type='primary'
              onClick={this.handleNext}
            >
              Create New Template
            </Button>
          </Row>
        </Spin>
      </FileTemplateWrapper>
    )
  }
}

export default connect(
  state => ({
    listTemplateLoading: state.Loading.LIST_TEMPLATE,
    fileTemplates: state.PartnerFileTemplate.fileTemplates,

    exportTemplateLoading: state.Loading.EXPORT_TEMPLATE,
    exportTemplateError: state.Error.EXPORT_TEMPLATE,

    changeTemplateStatusLoading: state.Loading.TEMPLATE_CHANGE_STATUS,
    changeTemplateStatusError: state.Error.TEMPLATE_CHANGE_STATUS
  }),
  {
    exportTemplate,
    resetErrorRedux,
    resetLoadingRedux,
    changeTemplateStatus,
    listFileTemplate
  }
)(ListTemplate)
