import React, { Component } from 'react'
import { AddConfigWrapper } from './component.style'
import { Form, Input, Select, Button, Row, Checkbox } from 'antd'

const FormItem = Form.Item
const { Option } = Select

class AddConfig extends Component {
  constructor (props) {
    super(props)
    this.state = {
      selectedPackageCodes: props.selectedPackageCodes
    }
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { edit } = this.props
        this.props.handleAddConfigValues(values, edit)
        this.props.form.resetFields()
      }
    })
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.selectedPackageCodes !== this.state.selectedPackageCodes) {
      this.setState({ selectedPackageCodes: nextProps.selectedPackageCodes })
    }
  }

  render () {
    const { form, timezones = [], editConfigData = {}, edit, defaultConfig } = this.props
    const { selectedPackageCodes = [] } = this.state
    const { getFieldDecorator } = form
    const {
      package_code: packageCode,
      filter_mapping: filterMapping = {},
      internal_filter: internalFilter = {},
      sql_query: sqlQuery
    } = editConfigData
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 6 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 12 }
      }
    }

    return (
      <AddConfigWrapper>
        <Form {...formItemLayout}>
          {
            (!defaultConfig || (edit && packageCode)) &&
            <FormItem label='Package Code'>
              {getFieldDecorator('package_code', {
                rules: [
                  { required: true, message: 'Please add package code!' }
                ],
                initialValue: packageCode
              })(
                <Select
                  placeholder='Select package code'
                  className='select'
                  optionFilterProp='children'
                  showSearch
                  filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
                >
                  {
                    selectedPackageCodes.map(value =>
                      <Option value={value} key={value}>
                        {value}
                      </Option>
                    )}
                </Select>
              )}
            </FormItem>
          }
          <FormItem label='Date filter mapping'>
            {getFieldDecorator('filter_mapping', {
              rules: [
                { required: true, message: '' }
              ],
              initialValue: filterMapping
            })(
              <div>
                <FormItem label='Start Date'>
                  {getFieldDecorator('start_date', {
                    rules: [
                      { required: true, message: 'Please add start date!' }
                    ],
                    initialValue: filterMapping && filterMapping['start_date']
                  })(
                    <Input placeholder='Start Date' />
                  )}
                </FormItem>
                <FormItem label='End Date'>
                  {getFieldDecorator('end_date', {
                    rules: [
                      { required: true, message: 'Please add end date!' }
                    ],
                    initialValue: filterMapping && filterMapping['end_date']
                  })(
                    <Input placeholder='End Date' />
                  )}
                </FormItem>
              </div>
            )}
          </FormItem>
          <FormItem label='Time zone filter'>
            {getFieldDecorator('internal_filter', {
              rules: [
                { required: true, message: '' }
              ],
              initialValue: internalFilter
            })(
              <div>
                <FormItem label='From Timezone'>
                  {getFieldDecorator('from_value', {
                    rules: [
                      { required: true, message: 'Please add From timezone!' }
                    ],
                    initialValue: internalFilter[0] && internalFilter[0]['timezone']['from_value']
                  })(
                    <Select
                      placeholder='Select from timezone'
                      className='select'
                      optionFilterProp='children'
                      showSearch
                      filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
                    >
                      {
                        timezones.map(timezone =>
                          <Option value={timezone} key={timezone}>
                            {timezone}
                          </Option>
                        )}
                    </Select>
                  )}
                </FormItem>
                <FormItem label='To timezone'>
                  {getFieldDecorator('to_value', {
                    rules: [
                      { required: true, message: 'Please add To Timezone!' }
                    ],
                    initialValue: internalFilter[0] && internalFilter[0]['timezone']['to_value']
                  })(
                    <Select
                      placeholder='Select To timezone'
                      className='select'
                      optionFilterProp='children'
                      showSearch
                      filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
                    >
                      {
                        timezones.map(timezone =>
                          <Option value={timezone} key={timezone}>
                            {timezone}
                          </Option>
                        )}
                    </Select>
                  )}
                </FormItem>
              </div>
            )}
          </FormItem>
          <FormItem label='Raw SQL Query'>
            {getFieldDecorator('raw_sql_query_check', {
              initialValue: !!sqlQuery
            })(
              <Checkbox defaultChecked={!!sqlQuery} />
            )}
          </FormItem>
          <FormItem label='SQL Query'>
            {getFieldDecorator('sql_query', {
              rules: [
                {
                  required: form.getFieldValue('raw_sql_query_check'),
                  message: 'Please add SQL query!'
                }
              ],
              initialValue: sqlQuery
            })(
              <Input.TextArea
                disabled={!form.getFieldValue('raw_sql_query_check')}
                rows={5}
                placeholder='SQL query'
              />
            )}
          </FormItem>
          <Row type='flex' justify='end'>
            <Button
              type='primary'
              // htmlType='submit'
              onClick={this.handleSubmit}
            >
              {
                edit
                  ? 'Update Config'
                  : 'Add Config'
              }
            </Button>
          </Row>
        </Form>
      </AddConfigWrapper>
    )
  }
}

const WrappedAddConfig = Form.create()(AddConfig)

export default WrappedAddConfig
