import React, { Component } from 'react'
import _ from 'lodash'
import { Form, Row, Button, Divider, Modal, Table, Col, notification, Select } from 'antd'
import { ReconFormWrapper } from './component.style'
import AddConfig from './addConfig'
import ViewConfig from './viewConfig'

const FormItem = Form.Item
const { Option } = Select

class ReconForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
      showAddConfigModal: false,
      defaultConfig: false,
      reconData: (Object.keys(props.templateData).length > 0 && props.templateData['recon_data']) || props.reconData || [],
      selectedPackageCodes: props.selectedPackageCodes,
      editConfigData: undefined,
      viewReconConfigData: undefined,
      viewReconConfig: false
    }
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.selectedPackageCodes !== this.state.selectedPackageCodes) {
      this.setState({ selectedPackageCodes: nextProps.selectedPackageCodes })
    }
  }

  handleAddConfigValues = (values, edit) => {
    const { reconData, editIndex } = this.state
    const finalValues = {}
    if (values['package_code'] && !edit) {
      const packageCodes = reconData.map(data => data['package_code'])
      if (packageCodes.includes(values['package_code'])) {
        notification['error']({ message: 'Duplicate Recon Config for Package Code' })
        this.setState({ showAddConfigModal: false })
        return
      }
    }
    values['filter_mapping'] = {}
    values['filter_mapping']['start_date'] = values['start_date']
    values['filter_mapping']['end_date'] = values['end_date']
    values['internal_filter'] = []
    values['internal_filter'][0] = {}
    values['internal_filter'][0]['timezone'] = {}
    values['internal_filter'][0]['timezone']['from_value'] = values['from_value']
    values['internal_filter'][0]['timezone']['to_value'] = values['to_value']
    values['internal_filter'][0]['timezone']['field'] = ['start_date', 'end_date']
    Object.assign(finalValues, {
      'filter_mapping': values['filter_mapping'],
      'internal_filter': values['internal_filter'],
      'sql_query': values['sql_query'],
      'package_code': values['package_code'] || null,
      'raw_sql_query_check': values['raw_sql_query_check']
    })
    // if (values['package_code']) {
    //   const index = selectedPackageCodes.indexOf(values['package_code'])
    //   if (index > -1) {
    //     selectedPackageCodes.splice(index, 1)
    //   }
    // }
    if (edit) {
      reconData[editIndex] = finalValues
    } else {
      reconData.push(finalValues)
    }
    this.setState({ reconData, showAddConfigModal: false })
    this.props.saveReconData(reconData)
  }

  handleEdit = (rowData, index) => {
    this.setState({ showAddConfigModal: true, editConfigData: rowData, editIndex: index, defaultConfig: !(rowData['package_code']) || false })
  }

  handleDelete = (index, rowData) => {
    const { reconData } = this.state
    reconData.splice(index, 1)
    this.setState({ reconData })
    this.props.saveReconData(reconData)
  }

  render () {
    const {
      form,
      timezones = [],
      templateData = {},
      columnsValues = [],
      operationType = ''
    } = this.props
    const {
      showAddConfigModal,
      defaultConfig,
      reconData,
      editConfigData,
      viewReconConfigData,
      viewReconConfig,
      selectedPackageCodes
    } = this.state
    const { getFieldDecorator } = form
    const {
      recon_csv_conversion_mapping: reconCsvConversionMapping = {}
    } = templateData
    const defaultConfigExists = _.filter(reconData, ['package_code', null])
    const columns = [{
      title: 'Package Code',
      dataIndex: 'package_code',
      key: 'package_code'
    }, {
      title: 'Date Filter Mapping',
      children: [{
        title: 'Start Date Key Field',
        dataIndex: 'filter_mapping.start_date',
        key: 'start_date'
      }, {
        title: 'End Date Key Field',
        dataIndex: 'filter_mapping.end_date',
        key: 'end_date'
      }]
    }, {
      title: 'Timezone Internal Filter',
      children: [{
        title: 'From Timezone',
        dataIndex: 'internal_filter[0].timezone.from_value',
        key: 'from_timezone'
      }, {
        title: 'To Timezone',
        dataIndex: 'internal_filter[0].timezone.to_value',
        key: 'to_timezone'
      }]
    }, {
      title: 'SQL Query',
      dataIndex: 'sql_query',
      key: 'sql_query'
    }, {
      title: 'Actions',
      dataIndex: 'name',
      key: 'actions',
      render: (value, row, index) => <Row type='flex' justify='space-around'>
        <Col className='view-button' onClick={() => this.setState({ viewReconConfig: true, viewReconConfigData: row })}>
          View
        </Col>
        <Col onClick={() => this.handleEdit(row, index)} className='edit-button'>
          Edit
        </Col>
        <Col onClick={() => this.handleDelete(index, row)} className='delete-button'>
          Delete
        </Col>
      </Row>
    }]

    return (
      <ReconFormWrapper>
        <Modal
          visible={showAddConfigModal}
          title={editConfigData ? 'Edit Recon Config' : 'Add Recon Config'}
          onCancel={() => this.setState({ showAddConfigModal: false, editConfigData: undefined })}
          width={700}
          footer={null}
        >
          <ReconFormWrapper>
            <AddConfig
              defaultConfig={defaultConfig}
              timezones={timezones}
              handleAddConfigValues={this.handleAddConfigValues}
              selectedPackageCodes={selectedPackageCodes}
              edit={editConfigData}
              editConfigData={editConfigData}
            />
          </ReconFormWrapper>
        </Modal>
        <Modal
          visible={viewReconConfig}
          title='Recon Config'
          onCancel={() => this.setState({ viewReconConfig: false, viewReconConfigData: undefined })}
          footer={null}
          width={500}
        >
          <ViewConfig
            viewConfigData={viewReconConfigData}
          />
        </Modal>

        <FormItem label='Recon Key Mapping'>
          {getFieldDecorator('config', {
            rules: [
              { required: true, message: '' }
            ],
            initialValue: reconCsvConversionMapping
          })(
            <div>
              <FormItem label='Unique Key'>
                {getFieldDecorator('unique_key', {
                  rules: [
                    { required: true, message: 'Please add unique key!' }
                  ],
                  initialValue: reconCsvConversionMapping && reconCsvConversionMapping['unique_key']
                })(
                  <Select
                    placeholder='Select Unique Key'
                    optionFilterProp='children'
                    showSearch
                    filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
                  >
                    {
                      columnsValues.map(({ expected, api_key: apiKey }) =>
                        <Option value={operationType === 'RECON' ? expected : apiKey} key={apiKey}>{expected}</Option>
                      )
                    }
                  </Select>
                )}
              </FormItem>
              <FormItem label='Premium'>
                {getFieldDecorator('premium', {
                  rules: [
                    { required: true, message: 'Please add premium!' }
                  ],
                  initialValue: reconCsvConversionMapping && reconCsvConversionMapping['premium']
                })(
                  <Select
                    placeholder='Select Premium'
                    optionFilterProp='children'
                    showSearch
                    filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
                  >
                    {
                      columnsValues.map(({ expected, api_key: apiKey }) =>
                        <Option value={operationType === 'RECON' ? expected : apiKey} key={apiKey}>{expected}</Option>
                      )
                    }
                  </Select>
                )}
              </FormItem>
            </div>
          )}
        </FormItem>
        <Divider />
        <Row type='flex' justify='end'>
          <Button
            type='primary'
            onClick={() => this.setState({ showAddConfigModal: true, defaultConfig: true })}
            disabled={defaultConfigExists.length !== 0}
          >
            Add Default Recon Config
          </Button>
          <Button
            type='primary'
            className='add-config-button'
            onClick={() => this.setState({ showAddConfigModal: true, defaultConfig: false })}
            disabled={(defaultConfigExists.length === 0) || (form.getFieldValue('package_code') && (reconData.length > (form.getFieldValue('package_code').length)))}
          >
            Add Recon Config
          </Button>
        </Row>
        <Table
          dataSource={reconData}
          columns={columns}
          bordered
        />
      </ReconFormWrapper>
    )
  }
}

export default ReconForm
