import React, { Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import {
  Form,
  Button,
  Select,
  Spin,
  Row,
  notification
} from 'antd'
import PolicyActions from '../../../../redux/policy/actions'
import { BasicFormWrapper } from './component.style'
import loadingAction from '../../../../redux/loading/actions'
import ErrorAction from '../../../../redux/error/actions'
import PartnerFileTemplateActions from '../../../redux/partnerFileTemplate/actions'

const { Option } = Select

const { getProducts, getPartners } = PolicyActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction
const { listFileTemplate } = PartnerFileTemplateActions

class BasicForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
    }
  }

  componentDidMount () {
    // this.props.getPartners()
    this.props.resetLoadingRedux(['GET_FILE_TEMPLATES', 'IMPORT_TEMPLATE'])
    this.props.resetErrorRedux(['GET_FILE_TEMPLATES', 'IMPORT_TEMPLATE'])
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.listTemplateLoading === false) {
      if (nextProps.listTemplateError === false) {
        this.props.nextStep()
      } else {
        notification['error']({ message: 'Error while fetching File templates' })
        this.props.stepStateChange('error')
      }
      this.props.resetLoadingRedux(['LIST_TEMPLATE'])
      this.props.resetErrorRedux(['LIST_TEMPLATE'])
    }
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        this.props.saveValues(values)
        this.props.stepStateChange('process')
        this.props.listFileTemplate({
          query: {
            ...values
          }
        })
      }
    })
  }

  handleClear = () => {
    this.props.form.resetFields()
  }

  handlePartnerChange = value => {
    this.props.form.resetFields(['product_code', 'package_code'])
    this.props.getProducts({ query: { partner_code: value } })
    this.setState({
      partnerCode: value
    })
  }

  render () {
    const {
      partners, partnersLoading,
      form, products,
      productsLoading,
      listTemplateLoading,
      fileTemplateStaticData,
      fileTemplateStaticDataLoading
    } = this.props
    const { getFieldDecorator } = form
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 4 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 16 }
      }
    }

    return (
      <BasicFormWrapper>
        <Spin spinning={!!listTemplateLoading}>
          <Form onSubmit={this.handleSubmit} className='login-form' {...formItemLayout}>
            <Form.Item label='Partner'>
              {getFieldDecorator('partner_code', {
                rules: [{ required: true, message: 'Please choose partner!' }]
              })(
                <Select
                  placeholder='Partner'
                  className='select'
                  showSearch
                  filterOption={(input, option) => option.props.children.join('').toLowerCase().includes(input.toLowerCase())}
                  onChange={this.handlePartnerChange}
                  loading={!!partnersLoading}
                  disabled={!!partnersLoading}
                >
                  {partners.map(({ name, code }) =>
                    <Option value={code} key={code}>{name} - {code}</Option>
                  )}
                </Select>
              )}
            </Form.Item>
            <Form.Item label='Product'>
              {getFieldDecorator('product_code')(
                <Select
                  placeholder='Product'
                  className='select'
                  showSearch
                  filterOption={(input, option) => option.props.value.toLowerCase().includes(input.toLowerCase())}
                  loading={!!productsLoading}
                  disabled={!!productsLoading || partners.length < 1}
                >
                  {products.map(({ name }) => (<Option value={name} key={name}>{name}</Option>))}
                </Select>
              )}
            </Form.Item>
            <Form.Item label='Template Type'>
              {getFieldDecorator('operation_type')(
                <Select
                  placeholder='Template Type'
                  className='select-multi'
                  showSearch
                  filterOption={(input, option) => option.props.value.toLowerCase().includes(input.toLowerCase())}
                  loading={!!fileTemplateStaticDataLoading}
                  disabled={!!fileTemplateStaticDataLoading || (Object.keys(fileTemplateStaticData).length > 0 && fileTemplateStaticData['operation-type-data'].length === 0)}
                >
                  {Object.keys(fileTemplateStaticData).length > 0 &&
                    fileTemplateStaticData['operation-type-data'].map(item =>
                      <Option value={item.value} key={item.value}>
                        {item.display_name}
                      </Option>
                    )}
                </Select>
              )}
            </Form.Item>
            <Row type='flex' justify='space-around'>
              <Button
                type='danger'
                onClick={this.handleClear}
              >
                Clear
              </Button>
              <Button
                type='primary'
                htmlType='submit'
                className='login-form-button'
              >
                Choose File Template
              </Button>
            </Row>
          </Form>
        </Spin>
      </BasicFormWrapper>
    )
  }
}

BasicForm.propTypes = {
  partners: PropTypes.array.isRequired,
  products: PropTypes.array.isRequired
}

BasicForm.defaultProps = {
  partners: [],
  products: []
}

const WrappedBasicForm = Form.create()(BasicForm)

export default connect(
  state => ({
    partners: state.Policy.partners,
    products: state.Policy.products,

    partnersLoading: state.Loading.GET_PARTNERS,
    partnersError: state.Error.GET_PARTNERS,

    productsLoading: state.Loading.GET_PRODUCTS,
    productsError: state.Error.GET_PRODUCTS,

    fileTemplateTypes: state.PartnerFileTemplate.fileTemplatesType,
    fileTemplateTypesLoading: state.Loading.GET_TEMPLATE_TYPES,

    fileTemplates: state.PartnerFileTemplate.fileTemplates,
    listTemplateLoading: state.Loading.LIST_TEMPLATE,
    listTemplateError: state.Error.LIST_TEMPLATE,

    fileTemplateStaticData: state.PartnerFileTemplate.fileTemplateStaticData,
    fileTemplateStaticDataLoading: state.Loading.GET_FILE_TEMPLATE_STATIC_DATA
  }),
  {
    getProducts,
    resetLoadingRedux,
    resetErrorRedux,
    getPartners,
    listFileTemplate
  }
)(WrappedBasicForm)
