import React, { Component } from 'react'
import { connect } from 'react-redux'
import { DoneWrapper } from './component.style'
import { Result, Button, Modal, Row, Col, Spin } from 'antd'
import PartnerFileTemplateActions from '../../../redux/partnerFileTemplate/actions'

const { getTemplateDetails } = PartnerFileTemplateActions

class Done extends Component {
  state = {
    viewDetails: false
  }

  renderRow = (key, value) => {
    return <Row>
      <Col span={8}>
        {key}
      </Col>
      <Col span={16}>
        {value}
      </Col>
    </Row>
  }

  renderColumnsData = (columns) => {
    return columns && columns.map(({ expected, api_key: apiKey, datetime_format: datetimeFormat, date_format: dateFormat, type, dropdown, required }) => {
      return [this.renderRow('Expected', expected),
        this.renderRow('Api Key', apiKey),
        this.renderRow('Type', type),
        this.renderRow('Date Time Format', datetimeFormat),
        this.renderRow('Date Format', dateFormat),
        this.renderRow('Required', required),
        this.renderRow('Dropdown Values', dropdown && dropdown.join(',')), <hr />]
    })
  }

  handleViewDetails = () => {
    const { createTemplateData } = this.props
    this.setState({ viewDetails: true })
    this.props.getTemplateDetails({
      query: {
        template_id: createTemplateData['template_id']
      }
    })
  }

  render () {
    const { createTemplateStatus, templateDetails = {}, templateDetailsLoading } = this.props
    const { viewDetails } = this.state
    const { id, name, partner = '', product_code: productCode, package_code: packageCode, operation_type: operationType,
      package_id: packageId, columns = '', recon_data: reconData = []
    } = templateDetails

    return (
      <DoneWrapper>
        <Modal
          visible={viewDetails}
          onCancel={() => this.setState({ viewDetails: false })}
          onOk={() => this.setState({ viewDetails: false })}
          title='File Template Details'
          width={600}
        >
          <Spin spinning={!!templateDetailsLoading}>
            <DoneWrapper>
              {this.renderRow('ID', id)}
              {this.renderRow('Name', name)}
              {this.renderRow('Partner', partner)}
              {this.renderRow('Product Code', productCode)}
              {this.renderRow('Package Code', packageCode)}
              {this.renderRow('Operation Type', operationType)}
              {this.renderRow('Package ID', packageId)}
              <Row>
                <Col span={8}>
                  Columns
                </Col>
                <Col span={16}>
                  {this.renderColumnsData(columns)}
                </Col>
              </Row>
              {
                reconData.map(({ package_code: packageCode, filter_mapping: filterMapping,
                  internal_filter: internalFilter, sql_query: sqlQuery }) => {
                  return <div>
                    {this.renderRow('Package Code', packageCode)}
                    <Row>
                      <Col span={8}>
                        Filter Mapping
                      </Col>
                      <Col span={16}>
                        {this.renderRow('Start Date', filterMapping['start_date'])}
                        {this.renderRow('End Date', filterMapping['end_date'])}
                      </Col>
                    </Row>
                    <Row>
                      <Col span={8}>
                        Internal Filter
                      </Col>
                      <Col span={16}>
                        {this.renderRow('From Timezone', internalFilter[0] && internalFilter[0]['timezone']['from_value'])}
                        {this.renderRow('To Timezone', internalFilter[0] && internalFilter[0]['timezone']['to_value'])}
                      </Col>
                    </Row>
                    {this.renderRow('SQL Query', sqlQuery)}
                    <hr />
                  </div>
                })
              }
            </DoneWrapper>
          </Spin>
        </Modal>
        <Result
          status='success'
          title={createTemplateStatus || 'File template created successfully!'}
          extra={[
            <Button onClick={this.handleViewDetails}>
              View Details
            </Button>,
            <Button onClick={() => this.props.resetData()}>
              Create Another File Template
            </Button>
          ]}
        />
      </DoneWrapper>
    )
  }
}

export default connect(state => ({
  createRecon: state.Recon.createRecon,
  createTemplateStatus: state.PartnerFileTemplate.createTemplateStatus,
  createTemplateData: state.PartnerFileTemplate.createTemplate,

  templateDetails: state.PartnerFileTemplate.templateDetails,
  templateDetailsLoading: state.Loading.GET_TEMPLATE_DETAILS
}), {
  getTemplateDetails
})(Done)
