import React, { Component } from 'react'
import { ViewConfigWrapper } from './component.style'
import { Row, Col } from 'antd'

class ViewConfig extends Component {
  renderKeyValue = (key, value) => {
    return <Row>
      <Col span={10}>
        {key}
      </Col>
      <Col span={14}>
        {value}
      </Col>
    </Row>
  }

  renderMultipleValueKey = (key, valueData) => {
    return <Row>
      <Col span={10}>
        {key}
      </Col>
      <Col span={14}>
        {
          valueData.map(({ key, value }) => this.renderKeyValue(key, value))
        }
      </Col>
    </Row>
  }

  render () {
    const { viewConfigData = {} } = this.props
    const { package_code: packageCode, filter_mapping: filterMapping = {},
      internal_filter: internalFilter = {}, sql_query: sqlQuery
    } = viewConfigData

    return (
      <ViewConfigWrapper>
        {this.renderKeyValue('Package Code', packageCode)}
        {this.renderMultipleValueKey('Filter Mapping',
          [
            { key: 'Start Date', value: filterMapping['start_date'] },
            { key: 'End Date', value: filterMapping['end_date'] }
          ]
        )}
        {this.renderMultipleValueKey('Timezone Data',
          [
            { key: 'From Timezone', value: internalFilter[0] && internalFilter[0]['timezone']['from_value'] },
            { key: 'To Timezone', value: internalFilter[0] && internalFilter[0]['timezone']['to_value'] }
          ]
        )}
        {this.renderKeyValue('SQL Query', sqlQuery)}
      </ViewConfigWrapper>
    )
  }
}

export default ViewConfig
