import React, { Component } from 'react'
import { ColumnFieldsWrapper } from './component.style'
import { Form, Input, Checkbox, Row, Select } from 'antd'

const FormItem = Form.Item
const { Option } = Select

class ColumnFields extends Component {
  constructor (props) {
    super(props)
    this.state = {
      dropdownValuesVisible: props.columnsData && props.columnsData.dropdown
    }
  }

  render () {
    const { form, index, columnTypes = [], columnsData = {}, dateTimeFormat = [], dateFormat } = this.props
    const { dropdownValuesVisible } = this.state
    const { expected, api_key: apiKey, required, type, datetime_format: datetimeFormat, date_format: dateFormatValue, dropdown } = columnsData
    const { getFieldDecorator } = form
    const columnType = form.getFieldValue(`type-${index}`)

    return (
      <ColumnFieldsWrapper>
        <Row type='flex' justify='space-between'>
          <FormItem label='File Field'>
            {getFieldDecorator(`expected-${index}`, {
              rules: [
                { required: true, message: 'Please add file field!' }
              ],
              initialValue: expected
            })(
              <Input placeholder='File Field' />
            )}
          </FormItem>
          <FormItem label='Api Key'>
            {getFieldDecorator(`api_key-${index}`, {
              rules: [
                { required: true, message: 'Please add api key!' }
              ],
              initialValue: apiKey
            })(
              <Input placeholder='API Field' />
            )}
          </FormItem>
        </Row>
        <Row type='flex' justify='space-between'>
          <FormItem label='Type'>
            {getFieldDecorator(`type-${index}`, {
              rules: [
                { required: true, message: 'Please add type!' }
              ],
              initialValue: type
            })(
              <Select
                placeholder='Select column Type'
                className='select'
                optionFilterProp='children'
                showSearch
                filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
              >
                {
                  columnTypes.map(({ display_name: displayName, value }) =>
                    <Option value={value} key={value}>
                      {displayName}
                    </Option>
                  )}
              </Select>
            )}
          </FormItem>
        </Row>
        {
          columnType === 'datetime' &&
          <FormItem label='Date Time Format'>
            {getFieldDecorator(`datetime_format-${index}`, {
              initialValue: datetimeFormat
            })(
              <Select
                placeholder='Select Date time format'
                className='select'
                optionFilterProp='children'
                showSearch
                filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
              >
                {
                  dateTimeFormat.map(({ display_name: displayName, value }) =>
                    <Option value={value} key={value}>
                      {displayName}
                    </Option>
                  )}
              </Select>
            )}
          </FormItem>
        }
        {
          columnType === 'date' &&
          <FormItem label='Date Format'>
            {getFieldDecorator(`date_format-${index}`, {
              initialValue: dateFormatValue
            })(
              <Select
                placeholder='Select Date format'
                className='select'
                optionFilterProp='children'
                showSearch
                filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
              >
                {
                  dateFormat.map(({ display_name: displayName, value }) =>
                    <Option value={value} key={value}>
                      {displayName}
                    </Option>
                  )}
              </Select>
            )}
          </FormItem>
        }
        Dropdown Values:
        <Checkbox
          defaultChecked={dropdown}
          className='dropdown-value'
          onChange={(e) => this.setState({ dropdownValuesVisible: e.target.checked })}
        />
        {
          dropdownValuesVisible &&
          <FormItem label='Dropdown Values'>
            {getFieldDecorator(`dropdown-${index}`, {
              initialValue: dropdown
            })(
              <Select mode='tags' className='dropdown' placeholder='Dropdown Values' />
            )}
          </FormItem>
        }
        <FormItem label='Required'>
          {getFieldDecorator(`required-${index}`, {
            initialValue: required === 'True'
          })(
            <Checkbox defaultChecked={required === 'True'} />
          )}
        </FormItem>
      </ColumnFieldsWrapper>
    )
  }
}

export default ColumnFields
