import React from 'react'
import { PackageDistributionFormWrapper } from './component.style'
import { Form, Input, Row, Select } from 'antd'

const FormItem = Form.Item
const { Option } = Select

const PackageDistribution = (props) => {
  const { getFieldDecorator } = props.form
  const packages = props.packages
  const length = packages.length || 1
  let customConfig = ''

  if (props.customConfig && props.customConfig.length > 2) {
    customConfig = props.customConfig
    customConfig = JSON.parse(customConfig.replaceAll('\'', '"'))
  }
  return (
    <PackageDistributionFormWrapper>
      {packages.map((packageName, index) => {
        let distribution = ''
        let sort = ''
        if (customConfig[packageName]) {
          distribution = (customConfig[packageName].distribution)
          sort = (customConfig[packageName].sort)
          if (sort > length) {
            sort = length
          }
        }
        return (
          <Row type='flex' justify='space-between' key={`row-${index}`}>
            <FormItem label={packageName} className='package-name'>
              {getFieldDecorator(`${packageName}-percentage`, {
                rules: [{ required: true, message: 'Please provide a value' }],
                initialValue: distribution || ''
              })(<Input placeholder='percent allotted' />)}
            </FormItem>

            <Row>
              <FormItem label='Priority'>
                {getFieldDecorator(`${packageName}-priority`, {
                  rules: [
                    { required: true, message: 'Please select priority' }
                  ],
                  initialValue: sort || index + 1
                })(
                  <Select
                    placeholder='Select priority'
                    className='select'
                    optionFilterProp='children'
                  >
                    {packages.map((packageName, index) => {
                      return (
                        <Option value={index + 1} key={index + 1}>
                          {index + 1}
                        </Option>
                      )
                    })}
                  </Select>
                )}
              </FormItem>
            </Row>
          </Row>
        )
      })}
    </PackageDistributionFormWrapper>
  )
}

export default PackageDistribution
